#include "rinkfit/joint_legacy_line_rechart_v1.hpp"
#include <iostream>
using namespace rinkfit;
using J=eventio::Json;
void check(bool ok,const char*why){if(!ok)throw std::runtime_error(why);}
JointEventModel load_model(const J&j){JointEventModel m;m.source_json=j;m.scene_block=j.at("scene_block");for(const auto&x:j.at("blocks")){EventParameterBlock b;b.name=x.at("name");b.values=x.at("values").get<std::vector<double>>();b.lower=x.at("lower").get<std::vector<double>>();b.upper=x.at("upper").get<std::vector<double>>();b.scales=x.at("scales").get<std::vector<double>>();m.blocks.push_back(b);}int mi=0;for(const auto&x:j.at("materials")){EventMaterial mat;mat.label=x.at("label");int pi=0;for(const auto&y:x.at("paths")){EventPath p;p.id=y.at("id");p.kind=y.at("kind");p.geometry_block=y.value("geometry_block",-1);p.physical_point=y.value("physical_point",false);p.provenance=y.value("provenance","");mat.paths.push_back(p);m.path_geometry_offsets[{mi,pi}]=y.value("geometry_offset",0);m.path_geometry_indices[{mi,pi}]=y.value("geometry_indices",std::vector<int>{});m.path_station_intervals[{mi,pi}]=y.value("allowed_station_intervals",std::vector<std::array<double,2>>{{0.,1.}});++pi;}m.materials.push_back(mat);++mi;}return m;}
int main(int argc,char**argv){try{check(argc==3,"request/output arguments");const auto req=eventio::read_json(argv[1]),original=eventio::read_json(req.at("original_model"));auto model=load_model(original);JointPacket packet;packet.source_hash=req.at("packet_sha256");packet.source_json={{"schema","rinkfit.joint_packet.v1"}};std::vector<std::uint8_t>physical;std::size_t query_count=0;
 for(const auto&x:req.at("rows")){JointObservation r;r.source_row_id=x.at("source_row_id");r.shot_id=x.at("shot_id");r.pts=x.at("pts");r.uv=x.at("uv").get<Vec2<double>>();r.material=x.at("material");r.path=x.at("path");r.kind=x.at("kind");r.station=x.at("station");r.row=x.at("row");r.alpha=x.at("alpha");r.active=x.at("active");if(r.kind==2){r.query=std::make_shared<JointQuery>();++query_count;}packet.rows.push_back(r);physical.push_back(x.at("physical").get<bool>()?1:0);}
 const J policy={{"blocks",req.at("blocks")},{"test_scope","all actual affected raw row ID/UV/PTS/kind/path/station/row/alpha; query pointer preserved, not evaluated"}};
 JointProblemBuilder core(model,packet);const auto before_station=core.station;const auto report=legacy_line_rechart_v1::apply_core(core,physical,policy,original);check(report.at("all_raw_world_points_preserved")==true,"raw world equivalence");check(query_count==450,"all original kind2 Query rows present");
 std::size_t physical_count=0,outside=0;for(std::size_t i=0;i<physical.size();++i){physical_count+=physical[i];outside+=core.station[i]<0||core.station[i]>1;if(physical[i])check(core.packet.rows[i].station_allowed(core.model,core.packet.rows[i].path,core.station[i],1e-12),"admitted source lost its mapped domain");}
 check(physical_count==47745&&outside==1360,"actual physical/inactive source denominator");
 const auto saved_station=core.station;const auto again=legacy_line_rechart_v1::apply_core(core,physical,policy,original);check(again.at("already_recharted")==true&&core.station==saved_station,"second application must not remap station");
 auto exported=original;exported[legacy_line_rechart_v1::metadata_key]=legacy_line_rechart_v1::metadata(core.model);for(std::size_t i=0;i<core.model.blocks.size();++i)exported["blocks"][i]["values"]=core.model.blocks[i].values;
 auto reloaded=load_model(exported);preserve_joint_legacy_line_rechart_metadata_v1(reloaded);reloaded.source_json=original;JointProblemBuilder resumed(std::move(reloaded),packet);resumed.station=saved_station;for(std::size_t i=0;i<resumed.packet.rows.size();++i)resumed.packet.rows[i].station=saved_station[i];const auto reload_report=restore_joint_legacy_line_domains_v1(resumed);check(reload_report.at("enabled")==true&&resumed.station==saved_station,"reload must only restore typed domains");
 for(std::size_t i=0;i<physical.size();++i)check(resumed.packet.rows[i].station_intervals(resumed.model,resumed.packet.rows[i].path)==core.packet.rows[i].station_intervals(core.model,core.packet.rows[i].path),"reloaded domain differs");
 // Explicit source-specific Query interval fixture: transform the interval, not alpha or source pixels.
 auto fixture_packet=packet;std::size_t qi=0;while(qi<fixture_packet.rows.size()&&fixture_packet.rows[qi].kind!=2)++qi;check(qi<fixture_packet.rows.size(),"query fixture missing");fixture_packet.rows[qi].station_domain_path=fixture_packet.rows[qi].path;fixture_packet.rows[qi].source_station_intervals={{.1,.8}};JointProblemBuilder fixture(model,fixture_packet);const auto fixture_result=legacy_line_rechart_v1::apply_core(fixture,physical,policy,original);const auto chart=legacy_line_rechart_v1::metadata(fixture.model);double a=0,b=1;for(const auto&x:chart.at("blocks"))if(x.at("geometry_block")==54){a=x.at("old_station_interval").at(0);b=x.at("old_station_interval").at(1);}const std::vector<std::array<double,2>>expected{{(.1-a)/(b-a),(.8-a)/(b-a)}};check(fixture.packet.rows[qi].source_station_intervals==expected&&fixture.alpha==core.alpha&&fixture.row==core.row,"Query source domain/alpha/row mapping");
 auto fixture_model=fixture.model;JointProblemBuilder fixture_reload(std::move(fixture_model),fixture_packet);fixture_reload.station=fixture.station;restore_joint_legacy_line_domains_v1(fixture_reload);check(fixture_reload.packet.rows[qi].source_station_intervals==expected,"Query interval cold replay");restore_joint_legacy_line_domains_v1(fixture_reload);check(fixture_reload.packet.rows[qi].source_station_intervals==expected,"Query interval idempotence");
 int rejections=0;for(int mode=0;mode<3;++mode){auto p=packet;auto mm=model;auto mask=physical;if(mode==0)p.rows[0].kind=1;if(mode==1){std::size_t i=0;while(i<physical.size()){const auto&row=p.rows[i];const int bi=mm.materials.at(row.material).paths.at(row.path).geometry_block;const auto&v=mm.blocks.at(bi).values;const double ss=before_station[i],x=v[0]*(1-ss)+v[2]*ss,y=v[1]*(1-ss)+v[3]*ss;if(!physical[i]&&EventModel::rink_membership(x,y,mm.blocks.at(mm.scene_block).values.data())>0.)break;++i;}check(i<physical.size(),"outside fixture");p.rows[i].active=true;mask[i]=1;}if(mode==2)mm.path_geometry_offsets[{145,0}]=1;JointProblemBuilder invalid(std::move(mm),std::move(p));const auto untouched=invalid.station;bool rejected=false;try{legacy_line_rechart_v1::apply_core(invalid,mask,policy,original);}catch(const std::exception&){rejected=true;}check(rejected&&invalid.station==untouched,"bad transform must fail before station mutation");++rejections;}
 J result={{"schema","rinkfit.actual_legacy_line_rechart_native_regression.v1"},{"passed",true},{"all_actual_affected_raw_rows",packet.rows.size()},{"physical_rows",physical_count},{"original_kind2_Query_rows",query_count},{"outside_raw_station_preserved",outside},{"same_process_idempotence",true},{"cold_typed_domain_replay",true},{"source_specific_Query_interval_fixture",true},{"negative_fixtures_rejected_before_mutation",rejections},{"actual",report},{"reload",reload_report},{"source_pixels_or_model_file_modified",false},{"solver_started",false}};eventio::atomic_json(argv[2],result);std::cout<<"PASS "<<packet.rows.size()<<" raw, "<<physical_count<<" physical, "<<outside<<" raw outside preserved"<<std::endl;return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
